s=s.replace('import type { Context as ModelContext, Tool } from "@earendil-works/pi-ai";','import type { Context as ModelContext } from "@earendil-works/pi-ai";')
s=s.replace('import { createLogger, fauxModels, tempDir } from "./test-helpers.ts";','import {\n\tcreateLogger,\n\tfauxModels,\n\ttempDir,\n\ttoolsOf,\n} from "./test-helpers.ts";')
open(p,'w').write(s)
p='src/test-helpers.ts'
s=open(p).read()
s=s.replace('import type { Api, Model } from "@earendil-works/pi-ai";','import type { Api, Context, Model, Tool } from "@earendil-works/pi-ai";')
s+='''
/** The tools a model request offers: its system messages' tools, added and removed in order. */
export function toolsOf(context: Context): Tool[] {
	const tools = new Map<string, Tool>();
	for (const message of context.messages) {
		if (message.role === "system") {
			for (const { name } of message.toolsRemoved ?? []) {
				tools.delete(name);
			}
			for (const added of message.toolsAdded ?? []) {
				tools.set(added.name, added);
			}
		}
	}
	return [...tools.values()];
}
'''
open(p,'w').write(s)
p='src/run.test.ts'
s=open(p).read()
s=s.replace("expect.stringMatching(/^🤖 faux\\S*\\/\\S+$/u),","expect.stringMatching(\n\t\t\t\t/^🤖 faux\\S*\\/\\S+ · tools: read, write, edit, bash$/u,\n\t\t\t),")
open(p,'w').write(s)
EOF
